// 协议伪代码：终态与资源接收分别认领
onNativeResult(operation, ownedResult):
    terminal = operation.claimTerminal()
    if terminal == rejected:
        handleDuplicateAccordingToTransferContract(ownedResult)
        return
    handoff = operation.prepareResultHandoff(ownedResult)
    resumeOnce(handoff, onUndelivered = cleanupWithMatchingBackend)
// resume 成功不等于调用者已取走资源；不得再发送错误终态
// native 工作归还与结果交接独立记录

